UPDATE supplier_settings SET default_packing_classification = CASE supplier_id WHEN 'd6718a29-e954-4c1b-bd84-03ea24884900' THEN 'commercial' WHEN 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0' THEN 'protective' WHEN 'd2734e23-d633-4819-bb15-e51aa44e2118' THEN 'protective' WHEN '841cd690-210a-422a-908c-7676828db272' THEN 'commercial' END, updated_at = now() WHERE supplier_id IN ('d6718a29-e954-4c1b-bd84-03ea24884900','bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0','d2734e23-d633-4819-bb15-e51aa44e2118','841cd690-210a-422a-908c-7676828db272');
